    /**
     * The host class name for [name] when it is an aliased `com.stardust` class or a nested class of one,
     * otherwise null. zh-CN: [name] 是别名表中的类或其嵌套类时返回宿主类名, 否则返回 null.
     */
    @JvmStatic
    fun resolve(name: String): String? {
        direct(name)?.let { return it }
        val nested = name.indexOf('$')
        if (nested > 0) {
            direct(name.substring(0, nested))?.let { return it + name.substring(nested) }
        }
        return null
    }

    private fun direct(name: String): String? = TABLE[name] ?: BEST_EFFORT[name]

